# ============================================================================
# Simulation analysis: figures and manuscript tables
# ============================================================================
# Input: scenario-level RDS data frames generated by the simulation scripts.
# Outputs: publication figures and three scenario-level summary tables (CSV).
# Set data_model and result_dir below before running this script.
# Tables use untrimmed replicate-level results; plotting filters do not affect
# manuscript means. Missing values are not replaced with zero.
# ============================================================================

############################################################
## Composition recovery: paired error difference from DGP model
## Select data_model = "ZIDM", "ZIMN", or "ZINB"
## Difference = error(method, replicate) - error(DGP baseline, same replicate)
## Positive = worse than baseline; negative = better.
############################################################

library(dplyr)
library(tidyr)
library(ggplot2)
library(patchwork)
library(ggh4x)

# ======================== USER SETTINGS ========================
data_model <- "ZIMN"   # "ZIDM", "ZIMN", "ZINB"
result_dir <- paste0("results_", data_model)
figure_dir <- paste0("figures_", data_model, "_calibrated")
# ==================== GLOBAL PLOT FONT SETTINGS ====================
PLOT_FONT <- list(
  base = 15,
  title = 16,
  strip = 14,
  axis_title = 16,
  axis_text = 15,
  legend_title = 17,
  legend_text = 16
)
# ================================================================

# Shared explanation displayed beneath every figure.
ZI_EXPLANATION <- paste(
  "Low ZI: U(0.05, 0.15)",
  "Medium ZI: U(0.20, 0.30)",
  "High ZI: U(0.35, 0.45)",
  sep = "     |     "
)

remove_extreme <- FALSE  # TRUE: suppress points outside 1.5*IQR within box groups
# Composition relative boxplots use metric-specific linear zoom windows.
# Zoom only changes the display; all paired differences remain in the CSV.
# ===============================================================

stopifnot(data_model %in% c("ZIDM", "ZIMN", "ZINB"))
dir.create(figure_dir, recursive = TRUE, showWarnings = FALSE)

# Read scenario RDS files produced by run_ZIDM_simulation().
# Each successful RDS is a data.frame with one row per replicate/method;
# FAILED_*.rds contains an error list and must be skipped.
files <- list.files(result_dir, pattern = "\\.rds$", full.names = TRUE)
files <- files[!grepl("^FAILED_", basename(files))]
if (!length(files)) stop("No successful RDS files in: ", result_dir)

raw_list <- vector("list", length(files))
for (i in seq_along(files)) {
  f <- files[[i]]
  cat(sprintf("Reading [%d/%d]: %s\n", i, length(files), f))
  x <- tryCatch(
    readRDS(f),
    error = function(e) {
      warning("Skipping unreadable RDS ", basename(f), ": ", conditionMessage(e))
      NULL
    }
  )
  if (is.data.frame(x)) {
    raw_list[[i]] <- x
  } else if (!is.null(x)) {
    warning("Skipping non-data.frame RDS: ", basename(f))
  }
}
raw_list <- Filter(Negate(is.null), raw_list)
if (!length(raw_list)) stop("No readable simulation data.frames in: ", result_dir)
df <- dplyr::bind_rows(raw_list)
cat("Loaded ", length(raw_list), " scenario files; ", nrow(df), " result rows.\n", sep = "")
df_raw <- df  # Keep all original methods and untrimmed replicate-level results.

required <- c("rep", "n", "m", "zi_level", "method",
              "Frobenius", "KL", "Shannon_MSE", "Simpson_MSE")
missing <- setdiff(required, names(df))
if (length(missing)) stop("Missing columns: ", paste(missing, collapse = ", "))

# Internal method names stay intact for reading and matching.
# Only figure labels are renamed.
method_lookup <- c(
  ZIDM_soft = "ZIDM", ZIMN_soft = "ZIMN",
  ZINB_gllvm = "ZINB", ZR = "ZR",
  ZIDM_k = "ZIDM-K", ZIDM_paper = "ZIDM-K"
)
method_order <- c("ZIDM", "ZIMN", "ZINB", "ZR", "ZIDM-K")
method_colors <- c(ZIDM = "#D62728", ZIMN = "#000000",
                   ZINB = "#1F77B4", ZR = "#2CA02C",
                   `ZIDM-K` = "#F2C94C")
method_shapes <- c(ZIDM = 16, ZIMN = 17, ZINB = 15, ZR = 18, `ZIDM-K` = 8)

# Keep only the main-comparison methods (exclude hard variants).
df <- df %>%
  dplyr::mutate(method_raw = as.character(method),
                method = unname(method_lookup[method_raw])) %>%
  dplyr::filter(!is.na(method)) %>%
  dplyr::mutate(
    dimension = dplyr::case_when(
      n == 50 & m == 100 ~ "n = 50, p = 100",
      n == 100 & m == 50 ~ "n = 100, p = 50",
      TRUE ~ NA_character_
    ),
    zi_level = factor(tolower(as.character(zi_level)),
                      levels = c("low", "medium", "high"),
                      labels = c("Low ZI", "Medium ZI", "High ZI"))
  ) %>%
  dplyr::filter(!is.na(dimension), !is.na(zi_level))

if (!nrow(df)) stop("No matching dimensions/ZI levels")

# IMPORTANT: A baseline must be matched within the same replicate,
# dimension, ZI scenario and metric. Do NOT subtract group means.
# Duplicate method/replicate rows are ambiguous; fail rather than mispair.
keys <- c("dimension", "zi_level", "rep", "method")
dup <- df %>% dplyr::count(dplyr::across(dplyr::all_of(keys))) %>%
  dplyr::filter(n > 1)
if (nrow(dup)) {
  stop("Duplicate (dimension, ZI, rep, method) keys detected. ",
       "Check whether the input folder mixes multiple scenario runs.")
}

metric_map <- c(Frobenius = "Frobenius", KL = "KL",
                Shannon_MSE = "Shannon MSE", Simpson_MSE = "Simpson MSE")
long <- df %>%
  dplyr::select(dplyr::all_of(keys), dplyr::all_of(names(metric_map))) %>%
  tidyr::pivot_longer(cols = dplyr::all_of(names(metric_map)),
                      names_to = "Metric_raw", values_to = "Error") %>%
  dplyr::mutate(Metric = unname(metric_map[Metric_raw]))

baseline_method <- data_model
baseline <- long %>%
  dplyr::filter(method == baseline_method) %>%
  dplyr::select(dimension, zi_level, rep, Metric, Baseline_error = Error)
if (!nrow(baseline)) stop("Baseline method ", baseline_method, " not found")

relative <- long %>%
  dplyr::left_join(baseline, by = c("dimension", "zi_level", "rep", "Metric")) %>%
  dplyr::mutate(Difference = Error - Baseline_error) %>%
  dplyr::filter(is.finite(Difference))

# Fail if a baseline is missing for a nonbaseline observation.
unmatched <- long %>%
  dplyr::left_join(baseline, by = c("dimension", "zi_level", "rep", "Metric")) %>%
  dplyr::filter(is.finite(Error) & !is.finite(Baseline_error))
if (nrow(unmatched)) warning(nrow(unmatched), " observations lack a finite matched baseline and are excluded.")

# Baseline is used for paired subtraction but omitted from the figure.
# Its difference is identically zero and adds no visual information.
relative <- relative %>%
  dplyr::filter(method != baseline_method) %>%
  dplyr::mutate(
    method = factor(method, levels = setdiff(method_order, baseline_method)),
    dimension = factor(dimension, levels = c("n = 50, p = 100", "n = 100, p = 50")),
    Metric = factor(Metric, levels = unname(metric_map))
  )

if (remove_extreme) {
  relative <- relative %>%
    dplyr::group_by(dimension, zi_level, Metric, method) %>%
    dplyr::mutate(q1 = quantile(Difference, .25, na.rm = TRUE),
                  q3 = quantile(Difference, .75, na.rm = TRUE),
                  iqr = q3 - q1,
                  Difference = ifelse(Difference < q1 - 1.5 * iqr |
                                        Difference > q3 + 1.5 * iqr,
                                      NA_real_, Difference)) %>%
    dplyr::ungroup() %>% dplyr::select(-q1, -q3, -iqr)
}

if (!nrow(relative)) stop("No matched finite non-baseline relative errors")

median_df <- relative %>%
  dplyr::group_by(dimension, zi_level, Metric, method) %>%
  dplyr::summarise(Median = median(Difference, na.rm = TRUE), .groups = "drop")

# Save paired differences for inspection and reproducibility.
out_prefix <- paste0(data_model, "_relative_to_", baseline_method, "_composition")
utils::write.csv(relative, file.path(figure_dir, paste0(out_prefix, "_paired_data.csv")), row.names = FALSE)

plot_method_order <- setdiff(method_order, baseline_method)

box_pos <- ggplot2::position_dodge2(width = .8, preserve = "single", padding = .06)
point_pos <- ggplot2::position_dodge(width = .8)

# Zoom each metric independently, using the box (Q1--Q3) range rather
# than the full range of replicate values. This keeps small differences
# visible without removing observations or changing boxplot statistics.
# Low/Medium/High share the same y-axis within each metric and dimension.
composition_zoom_padding <- 0.12

get_metric_zoom <- function(dat, metric_now) {
  z <- dat %>%
    dplyr::filter(as.character(Metric) == metric_now) %>%
    dplyr::group_by(zi_level, method) %>%
    dplyr::summarise(
      q1 = stats::quantile(Difference, 0.25, na.rm = TRUE),
      q3 = stats::quantile(Difference, 0.75, na.rm = TRUE),
      .groups = "drop"
    )
  if (!nrow(z)) return(c(-1, 1))
  limits <- range(c(z$q1, z$q3, 0), finite = TRUE)
  span <- diff(limits)
  if (!is.finite(span) || span == 0) {
    span <- max(abs(limits), 1e-4) * 0.2
  }
  limits + c(-1, 1) * composition_zoom_padding * span
}

make_dimension_plot <- function(dim_now) {
  dat <- relative %>% dplyr::filter(as.character(dimension) == dim_now)
  metric_limits <- lapply(unname(metric_map), function(m) get_metric_zoom(dat, m))
  names(metric_limits) <- unname(metric_map)
  
  # The limits are only a viewing window (oob_keep): no rows are discarded
  # before the boxplot quartiles/whiskers are calculated.
  ggplot2::ggplot(dat, ggplot2::aes(x = zi_level, y = Difference)) +
    ggplot2::geom_hline(yintercept = 0, linetype = "dashed",
                        color = "grey35", linewidth = .55) +
    ggplot2::geom_boxplot(
      ggplot2::aes(fill = method, color = method,
                   group = interaction(zi_level, method)),
      position = box_pos, width = .66, alpha = .72,
      linewidth = .36, outlier.shape = NA, na.rm = TRUE
    ) +
    ggh4x::facet_wrap2(ggplot2::vars(Metric), nrow = 2, ncol = 2,
                       scales = "free_y") +
    ggh4x::facetted_pos_scales(y = list(
      Metric == "Frobenius" ~ ggplot2::scale_y_continuous(
        limits = metric_limits[["Frobenius"]], oob = scales::oob_keep),
      Metric == "KL" ~ ggplot2::scale_y_continuous(
        limits = metric_limits[["KL"]], oob = scales::oob_keep),
      Metric == "Shannon MSE" ~ ggplot2::scale_y_continuous(
        limits = metric_limits[["Shannon MSE"]], oob = scales::oob_keep),
      Metric == "Simpson MSE" ~ ggplot2::scale_y_continuous(
        limits = metric_limits[["Simpson MSE"]], oob = scales::oob_keep)
    )) +
    ggplot2::scale_color_manual(values = method_colors, breaks = plot_method_order, drop = FALSE) +
    ggplot2::scale_fill_manual(values = method_colors, breaks = plot_method_order, drop = FALSE) +
    ggplot2::labs(title = dim_now, x = "Zero-inflation Level", y = NULL,
                  color = "Method", fill = "Method") +
    ggplot2::theme_bw(base_size = PLOT_FONT$base) +
    ggplot2::theme(
      plot.title = ggplot2::element_text(hjust = .5, face = "bold", size = PLOT_FONT$title),
      strip.background = ggplot2::element_rect(fill = "grey88", color = "grey45", linewidth = .35),
      strip.text = ggplot2::element_text(face = "bold", size = PLOT_FONT$strip),
      axis.text.x = ggplot2::element_text(size = PLOT_FONT$axis_text, color = "black"),
      axis.text.y = ggplot2::element_text(size = PLOT_FONT$axis_text, color = "black"),
      axis.title.x = ggplot2::element_text(size = PLOT_FONT$axis_title, face = "bold"),
      panel.grid.minor = ggplot2::element_blank(),
      panel.grid.major.x = ggplot2::element_blank(),
      panel.grid.major.y = ggplot2::element_line(color = "grey89", linewidth = .2),
      panel.spacing = grid::unit(2.5, "mm"),
      legend.position = "bottom",
      legend.title = ggplot2::element_text(face = "bold", size = PLOT_FONT$legend_title),
      legend.text = ggplot2::element_text(size = PLOT_FONT$legend_text)
    )
}

plots <- lapply(c("n = 50, p = 100", "n = 100, p = 50"), make_dimension_plot)
p_final <- (plots[[1]] | plots[[2]]) +
  patchwork::plot_layout(guides = "collect", widths = c(1, 1)) &
  ggplot2::theme(
    legend.position = "bottom",
    legend.direction = "horizontal",
    legend.title = ggplot2::element_text(size = PLOT_FONT$legend_title),
    legend.text = ggplot2::element_text(size = PLOT_FONT$legend_text)
  )
p_final <- p_final + patchwork::plot_annotation(
  caption = ZI_EXPLANATION,
  theme = ggplot2::theme(
    plot.caption = ggplot2::element_text(hjust = 0.5, size = PLOT_FONT$legend_text)
  )
)
print(p_final)

pdf_path <- file.path(figure_dir, paste0(out_prefix, "_boxplot.pdf"))
png_path <- file.path(figure_dir, paste0(out_prefix, "_boxplot.png"))
ggplot2::ggsave(pdf_path, p_final, width = 15, height = 7.8, device = grDevices::cairo_pdf)
ggplot2::ggsave(png_path, p_final, width = 15, height = 7.8, dpi = 300)
cat("\nSaved:\n", normalizePath(pdf_path), "\n", normalizePath(png_path), "\n")

############################################################
## APPENDIX ONLY: Soft vs hard classification
## Paired log2(error_hard / error_soft)
## Positive = soft is better; negative = hard is better.
## This comparison is independent of the DGP-baseline plot.
############################################################

appendix_metrics <- c(
  Frobenius = "Frobenius",
  KL = "KL",
  Shannon_MSE = "Shannon MSE",
  Simpson_MSE = "Simpson MSE",
  Procrustes = "Procrustes",
  zeta_Bias = "|zeta Bias|",
  zeta_RMSE = "zeta RMSE"
)

make_appendix_soft_hard <- function(raw_df, dgp, output_dir) {
  needed <- c("rep", "n", "m", "zi_level", "method", names(appendix_metrics))
  missing <- setdiff(needed, names(raw_df))
  if (length(missing)) {
    warning("Appendix plot skipped: missing columns: ", paste(missing, collapse = ", "))
    return(invisible(NULL))
  }
  
  soft_hard_names <- c(
    ZIDM_soft = "ZIDM-soft", ZIDM_hard = "ZIDM-hard",
    ZIMN_soft = "ZIMN-soft", ZIMN_hard = "ZIMN-hard"
  )
  dat <- raw_df %>%
    dplyr::mutate(method_raw = as.character(method)) %>%
    dplyr::filter(method_raw %in% names(soft_hard_names)) %>%
    dplyr::mutate(
      Method = unname(soft_hard_names[method_raw]),
      Family = ifelse(grepl("^ZIDM", Method), "ZIDM", "ZIMN"),
      Classification = ifelse(grepl("-soft$", Method), "Soft", "Hard"),
      dimension = dplyr::case_when(
        n == 50 & m == 100 ~ "(n,p) = (50,100)",
        n == 100 & m == 50 ~ "(n,p) = (100,50)",
        TRUE ~ NA_character_
      ),
      ZI = factor(tolower(as.character(zi_level)),
                  levels = c("low", "medium", "high"),
                  labels = c("Low ZI", "Medium ZI", "High ZI"))
    ) %>%
    dplyr::filter(!is.na(dimension), !is.na(ZI))
  
  if (!nrow(dat)) {
    warning("Appendix plot skipped: no soft/hard results found")
    return(invisible(NULL))
  }
  
  # Replicates must be uniquely paired within each scenario.
  # If the source contains multiple depth scenarios, pairing is ambiguous.
  pair_keys <- c("dimension", "ZI", "rep", "Family")
  dup <- dat %>% dplyr::count(dplyr::across(dplyr::all_of(c(pair_keys, "Classification")))) %>%
    dplyr::filter(n > 1)
  if (nrow(dup)) {
    stop("Appendix soft/hard pairing is ambiguous: duplicate replicate keys. ",
         "Separate distinct depth/scenario runs before plotting.")
  }
  
  long <- dat %>%
    dplyr::select(dplyr::all_of(c(pair_keys, "Classification", names(appendix_metrics)))) %>%
    tidyr::pivot_longer(cols = dplyr::all_of(names(appendix_metrics)),
                        names_to = "Metric_raw", values_to = "Error") %>%
    dplyr::mutate(
      Metric = unname(appendix_metrics[Metric_raw]),
      # Signed bias is not an error magnitude; compare absolute bias.
      Error = ifelse(Metric_raw == "zeta_Bias", abs(Error), Error)
    )
  
  paired <- long %>%
    tidyr::pivot_wider(names_from = Classification, values_from = Error) %>%
    dplyr::filter(is.finite(Soft), is.finite(Hard), Soft > 0, Hard > 0) %>%
    dplyr::mutate(
      Relative = log2(Hard / Soft),
      Family = factor(Family, levels = c("ZIDM", "ZIMN")),
      Metric = factor(
        Metric,
        levels = rev(unname(appendix_metrics))
      ),
      dimension = factor(dimension,
                         levels = c("(n,p) = (50,100)", "(n,p) = (100,50)"))
    )
  if (!nrow(paired)) {
    warning("Appendix plot skipped: no valid positive paired errors")
    return(invisible(NULL))
  }
  
  appendix_prefix <- paste0(dgp, "_appendix_soft_vs_hard_relative_recovery")
  utils::write.csv(paired, file.path(output_dir, paste0(appendix_prefix, "_paired_data.csv")),
                   row.names = FALSE)
  
  appendix_colors <- c("(n,p) = (50,100)" = "#0072B2",
                       "(n,p) = (100,50)" = "#D55E00")
  
  p <- ggplot2::ggplot(paired, ggplot2::aes(x = Relative, y = Metric,
                                            color = dimension, fill = dimension)) +
    ggplot2::geom_vline(xintercept = 0, linetype = "dashed",
                        linewidth = 0.6, color = "grey30") +
    ggplot2::geom_boxplot(position = ggplot2::position_dodge(width = 0.65),
                          width = 0.55, alpha = 0.20, outlier.shape = NA,
                          linewidth = 0.5, na.rm = TRUE) +
    ggplot2::facet_grid(rows = ggplot2::vars(Family), cols = ggplot2::vars(ZI),
                        drop = FALSE) +
    ggplot2::scale_color_manual(values = appendix_colors) +
    ggplot2::scale_fill_manual(values = appendix_colors) +
    ggplot2::coord_cartesian(xlim = c(-4, 4)) +
    ggplot2::scale_x_continuous(breaks = seq(-4, 4, 2)) +
    ggplot2::labs(x = expression(log[2](Classification/Conventional)), y = NULL,
                  color = "Dimension", fill = "Dimension",
                  caption = ZI_EXPLANATION) +
    ggplot2::theme_bw(base_size = PLOT_FONT$base) +
    ggplot2::theme(
      strip.background = ggplot2::element_rect(fill = "grey90", color = "grey60"),
      strip.text = ggplot2::element_text(face = "bold", size = PLOT_FONT$strip),
      panel.grid.minor = ggplot2::element_blank(),
      panel.grid.major.y = ggplot2::element_line(color = "grey90", linewidth = 0.25),
      legend.position = "bottom",
      axis.text.y = ggplot2::element_text(size = PLOT_FONT$axis_text),
      axis.text.x = ggplot2::element_text(size = PLOT_FONT$axis_text),
      axis.title = ggplot2::element_text(size = PLOT_FONT$axis_title),
      legend.title = ggplot2::element_text(size = PLOT_FONT$legend_title),
      legend.text = ggplot2::element_text(size = PLOT_FONT$legend_text),
      panel.spacing = grid::unit(2.5, "mm"),
      plot.caption = ggplot2::element_text(hjust = 0.5, size = PLOT_FONT$legend_text)
    )
  
  print(p)
  ggplot2::ggsave(file.path(output_dir, paste0(appendix_prefix, ".pdf")),
                  p, width = 12, height = 7, device = grDevices::cairo_pdf)
  ggplot2::ggsave(file.path(output_dir, paste0(appendix_prefix, ".png")),
                  p, width = 12, height = 7, dpi = 300)
  cat("\n[APPENDIX] Saved: ", appendix_prefix, ".pdf/.png\n", sep = "")
  invisible(p)
}

# Appendix figure for each selected DGP (e.g. ZIDM or ZINB).
p_appendix_soft_hard <- make_appendix_soft_hard(df_raw, data_model, figure_dir)


############################################################
## PARAMETER RECOVERY (MAIN TEXT): Bias | RMSE
## Read directly from the same simulation RDS data.frames.
## Rows = beta1 / beta2 / zeta; columns = Low / Medium / High.
## Same x-axis limits across the three ZI panels of each
## parameter row; different rows may have different limits.
############################################################

parameter_columns <- c(
  beta1_Bias = "beta1", beta2_Bias = "beta2", zeta_Bias = "zeta",
  beta1_RMSE = "beta1", beta2_RMSE = "beta2", zeta_RMSE = "zeta"
)

missing_parameter_cols <- setdiff(names(parameter_columns), names(df))
if (length(missing_parameter_cols)) {
  warning("Parameter plot skipped; missing RDS columns: ",
          paste(missing_parameter_cols, collapse = ", "))
} else {
  parameter_df <- df %>%
    dplyr::select(dimension, zi_level, method,
                  dplyr::all_of(names(parameter_columns))) %>%
    tidyr::pivot_longer(
      cols = dplyr::all_of(names(parameter_columns)),
      names_to = "column", values_to = "Value"
    ) %>%
    dplyr::mutate(
      Metric = ifelse(grepl("_Bias$", column), "Bias", "RMSE"),
      Parameter = unname(parameter_columns[column]),
      Parameter = factor(Parameter, levels = c("beta1", "beta2", "zeta"),
                         labels = c("beta[1]", "beta[2]", "zeta")),
      dimension = factor(as.character(dimension),
                         levels = c("n = 50, p = 100", "n = 100, p = 50")),
      method = factor(as.character(method), levels = method_order)
    ) %>%
    dplyr::filter(is.finite(Value),
                  as.character(method) %in% c("ZIDM", "ZIMN", "ZINB", "ZIDM-K"))
  parameter_df <- parameter_df %>%
    group_by(
      dimension,
      zi_level,
      method,
      Parameter,
      Metric
    ) %>%
    summarise(
      Value = mean(Value, na.rm = TRUE),
      .groups = "drop"
    )
  if (nrow(parameter_df)) {
    utils::write.csv(parameter_df,
                     file.path(figure_dir, paste0(data_model, "_parameter_Bias_RMSE_figure_data.csv")),
                     row.names = FALSE)
    
    parameter_dimension_colors <- c(
      "n = 50, p = 100" = "#0072B2",
      "n = 100, p = 50" = "#D55E00"
    )
    parameter_dimension_shapes <- c(
      "n = 50, p = 100" = 16,
      "n = 100, p = 50" = 17
    )
    
    make_parameter_metric_plot <- function(metric_now) {
      dat <- parameter_df %>%
        dplyr::filter(Metric == metric_now) %>%
        dplyr::mutate(method = factor(
          as.character(method),
          levels = c("ZIDM-K", "ZINB", "ZIMN", "ZIDM")
        ))
      
      # Highlight the DGP-matched method in every parameter/ZI panel.
      highlight_y <- match(data_model, levels(dat$method))
      highlight_df <- dat %>%
        dplyr::distinct(Parameter, zi_level) %>%
        dplyr::mutate(
          xmin = -Inf, xmax = Inf,
          ymin = highlight_y - 0.5,
          ymax = highlight_y + 0.5
        )
      
      row_limits <- function(par) {
        x <- dat$Value[as.character(dat$Parameter) == par]
        x <- x[is.finite(x)]
        if (!length(x)) return(c(-1, 1))
        bounds <- range(x)
        if (metric_now == "Bias") bounds <- range(c(bounds, 0))
        padding <- max(diff(bounds) * 0.08, 0.0001)
        bounds + c(-padding, padding)
      }
      p <- ggplot2::ggplot(dat,
                           ggplot2::aes(x = Value, y = method,
                                        color = dimension, shape = dimension)) +
        ggplot2::geom_rect(
          data = highlight_df,
          ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
          inherit.aes = FALSE,
          fill = "grey92", color = NA
        ) +
        ggplot2::geom_hline(yintercept = c(1.5, 2.5, 3.5),
                            color = "grey88", linewidth = 0.4) +
        {if (metric_now == "Bias") ggplot2::geom_vline(
          xintercept = 0, linetype = "dashed", color = "grey25", linewidth = 0.8)} +
        ggplot2::geom_point(
          position = ggplot2::position_dodge(width = 0.45),
          size = 2.2, stroke = 0.5, na.rm = TRUE) +
        ggh4x::facet_grid2(
          rows = ggplot2::vars(Parameter), cols = ggplot2::vars(zi_level),
          scales = "free_x", independent = "x",
          labeller = ggplot2::labeller(Parameter = ggplot2::label_parsed)
        ) +
        ggh4x::facetted_pos_scales(x = list(
          Parameter == "beta[1]" ~ ggplot2::scale_x_continuous(limits = row_limits("beta[1]"), breaks = scales::breaks_pretty(n = 3)),
          Parameter == "beta[2]" ~ ggplot2::scale_x_continuous(limits = row_limits("beta[2]"), breaks = scales::breaks_pretty(n = 3)),
          Parameter == "zeta" ~ ggplot2::scale_x_continuous(limits = row_limits("zeta"), breaks = scales::breaks_pretty(n = 3))
        )) +
        ggplot2::scale_color_manual(values = parameter_dimension_colors) +
        ggplot2::scale_shape_manual(values = parameter_dimension_shapes) +
        ggplot2::labs(title = metric_now, x = NULL, y = NULL,
                      color = "Dimension", shape = "Dimension") +
        ggplot2::theme_bw(base_size = PLOT_FONT$base) +
        ggplot2::theme(
          plot.title = ggplot2::element_text(hjust = 0.5, face = "bold", size = PLOT_FONT$title),
          strip.background = ggplot2::element_rect(fill = "grey90", color = "grey60"),
          strip.text = ggplot2::element_text(face = "bold", size = PLOT_FONT$strip),
          axis.text.x = ggplot2::element_text(size = PLOT_FONT$axis_text),
          axis.text.y = ggplot2::element_text(size = PLOT_FONT$axis_text),
          axis.title = ggplot2::element_text(size = PLOT_FONT$axis_title),
          legend.title = ggplot2::element_text(size = PLOT_FONT$legend_title),
          legend.text = ggplot2::element_text(size = PLOT_FONT$legend_text),
          panel.grid = ggplot2::element_blank(),
          panel.spacing = grid::unit(1.5, "mm"),
          legend.position = "bottom"
        )
      p
    }
    
    # Show beta1 / beta2 / zeta row-strip labels only on the far right (RMSE).
    p_bias <- make_parameter_metric_plot("Bias") +
      ggplot2::theme(
        strip.text.y.right = ggplot2::element_blank(),
        strip.background.y = ggplot2::element_blank()
      )
    p_rmse <- make_parameter_metric_plot("RMSE")
    
    p_parameter <- (p_bias | p_rmse) +
      patchwork::plot_layout(guides = "collect", widths = c(1, 1)) &
      ggplot2::theme(
        legend.position = "bottom",
        legend.direction = "horizontal",
        legend.title = ggplot2::element_text(size = PLOT_FONT$legend_title),
        legend.text = ggplot2::element_text(size = PLOT_FONT$legend_text)
      )
    p_parameter <- p_parameter + patchwork::plot_annotation(
      caption = ZI_EXPLANATION,
      theme = ggplot2::theme(
        plot.caption = ggplot2::element_text(hjust = 0.5, size = PLOT_FONT$legend_text)
      )
    )
    print(p_parameter)
    param_prefix <- paste0(data_model, "_parameter_Bias_RMSE")
    ggplot2::ggsave(file.path(figure_dir, paste0(param_prefix, ".pdf")),
                    p_parameter, width = 12, height = 7,
                    device = grDevices::cairo_pdf)
    ggplot2::ggsave(file.path(figure_dir, paste0(param_prefix, ".png")),
                    p_parameter, width = 12, height = 7, dpi = 300)
    cat("[PARAMETER] Saved: ", param_prefix, ".pdf/.png\n", sep = "")
  } else {
    warning("Parameter plot skipped: no finite parameter recovery results")
  }
}


# ============================================================================
# MANUSCRIPT TABLES: SCENARIO-LEVEL MEANS
# ============================================================================
# All three tables are computed from df_raw (before figure-only filtering).
# A scenario is defined by n, m, zero-inflation level and, when present,
# sequencing depth. Each method is summarized separately.
# The simulation generator uses m for the number of taxa (often denoted p).
# The outputs contain one row per scenario and method, with valid counts.
#
# IMPORTANT: runtime is fitting time only. Do not substitute runtime_total,
# ci_runtime, or generation_runtime for this quantity.
# CI coverage and width are already calculated per replicate by the simulation
# code. Means below are unweighted averages across valid replicate summaries.
# This is NOT pooled coefficient-level coverage when nValid varies by replicate.
# ============================================================================

TABLE_DIR <- file.path(figure_dir, "manuscript_tables")
dir.create(TABLE_DIR, recursive = TRUE, showWarnings = FALSE)

# Retain internal method labels to avoid merging soft/hard classifications.
table_method_names <- c(
  ZIDM_soft = "ZIDM-LVM (soft)",
  ZIDM_hard = "ZIDM-LVM (hard)",
  ZIMN_soft = "ZIMN-LVM (soft)",
  ZIMN_hard = "ZIMN-LVM (hard)",
  ZINB_gllvm = "ZINB-LVM",
  ZIDM_k = "ZIDM-K", ZIDM_paper = "ZIDM-K",
  ZR = "ZR"
)

prepare_table_data <- function(raw, dgp) {
  keys <- c("rep", "n", "m", "zi_level", "method")
  missing <- setdiff(keys, names(raw))
  if (length(missing)) stop("Table data missing columns: ", paste(missing, collapse = ", "))
  dat <- raw
  dat$method_raw <- as.character(dat$method)
  dat$method <- unname(table_method_names[dat$method_raw])
  dat$method[is.na(dat$method)] <- dat$method_raw[is.na(dat$method)]
  dat$zi_level <- tolower(as.character(dat$zi_level))
  dat$DGP <- dgp
  # Preserve optional scenario factors if supplied by the generator.
  group_vars <- c("DGP", "n", "m", "zi_level")
  for (candidate in c("depth_level", "depth", "sequencing_depth")) {
    if (candidate %in% names(dat)) group_vars <- c(group_vars, candidate)
  }
  group_vars <- c(group_vars, "method")
  # A duplicate indicates mixed runs or repeated method labels in a scenario.
  # The distinct raw method is included so soft/hard do not get confused.
  unique_keys <- c(setdiff(group_vars, "method"), "method_raw", "rep")
  duplicate_rows <- dat %>%
    dplyr::count(dplyr::across(dplyr::all_of(unique_keys)),
                 name = ".duplicate_count") %>%
    dplyr::filter(.data$.duplicate_count > 1)
  if (nrow(duplicate_rows)) {
    stop("Duplicate scenario/method/replicate records detected in table input. ",
         "Check whether the result directory mixes simulation runs.")
  }
  list(data = dat, groups = c(group_vars, "method_raw"))
}

# Summarize one numeric measurement per replicate; include sample counts.
scenario_mean <- function(dat, groups, value_col, label) {
  if (!value_col %in% names(dat)) {
    warning("Missing column for ", label, ": ", value_col,
            "; output will contain NA rather than fabricated values.")
    dat[[value_col]] <- NA_real_
  }
  dat %>%
    dplyr::group_by(dplyr::across(dplyr::all_of(groups))) %>%
    dplyr::summarise(
      Mean = {
        v <- suppressWarnings(as.numeric(.data[[value_col]]))
        if (any(is.finite(v))) mean(v[is.finite(v)]) else NA_real_
      },
      N_valid = sum(is.finite(suppressWarnings(as.numeric(.data[[value_col]])))),
      N_replicates = dplyr::n_distinct(.data$rep),
      .groups = "drop"
    ) %>%
    dplyr::mutate(Metric = label, .before = "Mean")
}

# TABLE 1: Mean Procrustes error for each simulation scenario.
make_procrustes_table <- function(prepared) {
  scenario_mean(prepared$data, prepared$groups,
                "Procrustes", "Procrustes error")
}

# TABLE 2: Mean model fitting time (seconds); CI time is excluded.
make_fitting_time_table <- function(prepared) {
  scenario_mean(prepared$data, prepared$groups,
                "runtime", "Fitting time (s)")
}

# TABLE 3: Mean CI width and coverage for beta0, beta1 and beta2.
# Coverage is a proportion on [0,1], not a percentage on [0,100].
# Validity diagnostics are reported separately when available.
make_ci_coverage_table <- function(prepared) {
  dat <- prepared$data
  groups <- prepared$groups
  spec <- c(
    beta0_meanCIWidth = "beta0 | CI width",
    beta0_Coverage = "beta0 | Coverage",
    beta1_meanCIWidth = "beta1 | CI width",
    beta1_Coverage = "beta1 | Coverage",
    beta2_meanCIWidth = "beta2 | CI width",
    beta2_Coverage = "beta2 | Coverage",
    beta0_validProp = "beta0 | Valid CI proportion",
    beta1_validProp = "beta1 | Valid CI proportion",
    beta2_validProp = "beta2 | Valid CI proportion"
  )
  pieces <- lapply(names(spec), function(col) {
    scenario_mean(dat, groups, col, unname(spec[[col]]))
  })
  dplyr::bind_rows(pieces) %>%
    dplyr::mutate(
      Parameter = sub(" \\|.*$", "", .data$Metric),
      Statistic = sub("^.*\\| ", "", .data$Metric)
    )
}

# Execute all table builders and export reproducible CSV files.
prepared_tables <- prepare_table_data(df_raw, data_model)
procrustes_table <- make_procrustes_table(prepared_tables)
fitting_time_table <- make_fitting_time_table(prepared_tables)
ci_coverage_table <- make_ci_coverage_table(prepared_tables)

utils::write.csv(procrustes_table,
                 file.path(TABLE_DIR, paste0(data_model, "_mean_procrustes.csv")),
                 row.names = FALSE, na = "")
utils::write.csv(fitting_time_table,
                 file.path(TABLE_DIR, paste0(data_model, "_mean_fitting_time.csv")),
                 row.names = FALSE, na = "")
utils::write.csv(ci_coverage_table,
                 file.path(TABLE_DIR, paste0(data_model, "_mean_ci_coverage.csv")),
                 row.names = FALSE, na = "")
message("Manuscript tables saved in: ", normalizePath(TABLE_DIR))
